#include <cstddef>
#include <initializer_list>
#include <iostream>
#include <memory>
#include <utility>

class SinglyQueue {
    struct Node {
        int value;
        std::unique_ptr<Node> next;
        explicit Node(int item) : value(item) {}
    };

    std::unique_ptr<Node> head_;
    Node* tail_ = nullptr; // Borrowed: never deletes a node.
    std::size_t size_ = 0;

public:
    static constexpr std::size_t capacity = 64;
    SinglyQueue() = default;
    SinglyQueue(const SinglyQueue&) = delete;
    SinglyQueue& operator=(const SinglyQueue&) = delete;
    SinglyQueue(SinglyQueue&&) = delete;
    SinglyQueue& operator=(SinglyQueue&&) = delete;
    ~SinglyQueue() { clear(); }

    std::size_t size() const noexcept { return size_; }

    bool try_push(int value) {
        if (size_ == capacity) return false;
        auto fresh = std::make_unique<Node>(value);
        Node* const added = fresh.get();
        if (tail_ != nullptr) {
            tail_->next = std::move(fresh);
        } else {
            head_ = std::move(fresh);
        }
        tail_ = added;
        ++size_;
        return true;
    }

    bool try_pop(int& out) noexcept {
        if (!head_) return false;
        auto old_head = std::move(head_);
        out = old_head->value;
        head_ = std::move(old_head->next);
        --size_;
        if (!head_) tail_ = nullptr;
        return true; // old_head now owns just the removed node.
    }

    void clear() noexcept {
        int ignored = 0;
        while (try_pop(ignored)) {}
    }

    // Diagnostic for states produced by this class, not arbitrary memory.
    bool invariant_holds() const noexcept {
        if (size_ > capacity) return false;
        const Node* current = head_.get();
        const Node* last = nullptr;
        std::size_t reached = 0;
        while (current != nullptr) {
            if (reached == capacity) return false;
            ++reached;
            last = current;
            current = current->next.get();
        }
        return reached == size_ && last == tail_;
    }
};

int main() {
    SinglyQueue queue;
    std::cout << std::boolalpha;
    std::cout << "empty: size=" << queue.size()
              << " valid=" << queue.invariant_holds() << '\n';
    int item = -99;
    const bool empty_pop = queue.try_pop(item);
    std::cout << "pop empty: " << empty_pop << " out=" << item << '\n';

    for (const int value : {14, 8, 14}) {
        std::cout << "push " << value << ": " << queue.try_push(value) << '\n';
    }
    while (queue.try_pop(item)) {
        std::cout << "pop: value=" << item << " size=" << queue.size() << '\n';
    }
    std::cout << "after drain: valid=" << queue.invariant_holds() << '\n';
    std::cout << "push after drain: " << queue.try_push(21) << '\n';
    queue.clear();
    std::cout << "after clear: size=" << queue.size()
              << " valid=" << queue.invariant_holds() << '\n';

    std::size_t accepted = 0;
    for (std::size_t i = 0; i < SinglyQueue::capacity; ++i) {
        if (queue.try_push(static_cast<int>(i))) ++accepted;
    }
    const bool overflow = queue.try_push(999);
    std::cout << "accepted=" << accepted << " overflow=" << overflow
              << " size=" << queue.size()
              << " valid=" << queue.invariant_holds() << '\n';
} // The destructor also clears a nonempty queue iteratively.
